alunos = {
    "Ana": 8.5,
    "Bruno": 6.0,
    "Carla": 9.2,
    "Diego": 7.0
}

aprovados = {}
reprovados = {}

for nome, nota in alunos.items():
    if nota >= 7:
        situacao = "Aprovado"
        aprovados[nome] = nota
    else:
        situacao = "Reprovado"
        reprovados[nome] = nota

    print(nome, "-", nota, "-", situacao)

print("Aprovados:", aprovados)
print("Reprovados:", reprovados)

