class ContaBancaria:
    def __init__(self, titular, saldo):
        self.titular = titular
        self.saldo = saldo

    def depositar(self, valor):
        if valor > 0:
            self.saldo = self.saldo + valor
            print("Depósito realizado:", valor)
        else:
            print("Valor de depósito inválido")

    def sacar(self, valor):
        if valor <= 0:
            print("Valor de saque inválido")
        elif valor <= self.saldo:
            self.saldo = self.saldo - valor
            print("Saque realizado:", valor)
        else:
            print("Saldo insuficiente")

    def exibir_saldo(self):
        print(self.titular, "tem saldo de", self.saldo)


conta = ContaBancaria("Ana", 100)

conta.depositar(50)
conta.sacar(30)
conta.depositar(25)
conta.sacar(200)

conta.exibir_saldo()

try_except:
valores = ["10", "abc", "0", "7", "25"]

for texto in valores:
    try:
        numero = int(texto)
        resultado = 100 / numero
        print(texto, "->", resultado)
    except ValueError:
        print(texto, "-> não é um número válido")
    except ZeroDivisionError:
        print(texto, "-> não é possível dividir por zero")
    finally:
        print("Processamento finalizado para:", texto)

print("Todos os valores foram processados")
